$r=dirname(__DIR__);require_once $r.'/app/foundation.php';require_once $r.'/company/admin/core/functions.php';require_once $r.'/company/admin/modules/accounting-finance/functions.php';require_once $r.'/company/admin/modules/accounting-finance/core.php';require_once $r.'/company/admin/modules/accounting-finance/tax.php';require_once $r.'/company/admin/modules/accounting-finance/ledger.php';require_once $r.'/company/admin/modules/accounting-finance/invoices.php';require_once $r.'/company/admin/modules/accounting-finance/payments.php';require_once $r.'/company/admin/modules/accounting-finance/planning.php';require_once $r.'/company/admin/modules/accounting-finance/reports.php';function report_assert(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}yovel_admin_accounting_finance_schema();yovel_admin_finance_core_schema();yovel_admin_general_ledger_schema();yovel_admin_finance_invoice_schema();$d=bx_db();$f=$d->GetRow("SELECT c.company_key,c.company_key_hash,c.company_name,a.admin_key FROM project_company c JOIN project_company_admin a ON a.company_key_hash=c.company_key_hash AND a.admin_status='ACTIVE' LIMIT 1");$c=['company_key'=>$f['company_key'],'company_key_hash'=>$f['company_key_hash'],'company_name'=>$f['company_name']];$a=['admin_key'=>$f['admin_key']];$s=strtoupper(substr(str_replace('-','',bx_uuid()),0,8));$keys=['cash'=>bx_uuid(),'equity'=>bx_uuid(),'income'=>bx_uuid(),'expense'=>bx_uuid(),'sales'=>bx_uuid(),'purchase'=>bx_uuid()];$sql="INSERT INTO project_company_accounting_account(account_key,company_key,company_key_hash,account_code,account_name,root_type,report_type,account_type,account_currency,is_group,balance_must_be,account_status,created_by_admin_key,updated_by_admin_key) VALUES(?,?,?,?,?,?,?,?,'PHP',0,'EITHER','ACTIVE',?,?)";foreach([['cash','CASH','ASSET','BALANCE_SHEET','Cash'],['equity','EQ','EQUITY','BALANCE_SHEET','Equity'],['income','INC','INCOME','PROFIT_LOSS','Income Account'],['expense','EXP','EXPENSE','PROFIT_LOSS','Expense Account']] as [$n,$co,$rt,$rep,$t])$d->Execute($sql,[$keys[$n],$c['company_key'],$c['company_key_hash'],$co.'_'.$s,$co.' '.$s,$rt,$rep,$t,$a['admin_key'],$a['admin_key']]);try{yovel_admin_post_general_ledger_transaction($d,$c,$a,['posting_date'=>'2026-01-01','voucher_type'=>'OWNER_FUNDING','voucher_no'=>'FUND-'.$s,'source_module'=>'OWNER_FUNDING','entries'=>[['account_key'=>$keys['cash'],'debit'=>'1000','credit'=>'0'],['account_key'=>$keys['equity'],'debit'=>'0','credit'=>'1000']]]);yovel_admin_post_general_ledger_transaction($d,$c,$a,['posting_date'=>'2026-02-01','voucher_type'=>'TEST','voucher_no'=>'OPS-'.$s,'source_module'=>'TEST','entries'=>[['account_key'=>$keys['cash'],'debit'=>'500','credit'=>'0'],['account_key'=>$keys['income'],'debit'=>'0','credit'=>'500'],['account_key'=>$keys['expense'],'debit'=>'100','credit'=>'0'],['account_key'=>$keys['cash'],'debit'=>'0','credit'=>'100']]]);$pl=yovel_admin_profit_loss_report($c,'2026-01-01','2026-12-31');report_assert($pl['net_profit_loss']==='400.000000','Profit/Loss report failed.');$bs=yovel_admin_balance_sheet_report($c,'2026-12-31');report_assert($bs['total_assets']==='1400.000000'&&$bs['difference']==='0.000000','Balance Sheet failed.');$cf=yovel_admin_cash_flow_report($c,'2026-01-01','2026-12-31');report_assert($cf['net_cash_change']==='1400.000000','Cash Flow failed.');$header="INSERT INTO project_company_finance_invoice(invoice_key,company_key,company_key_hash,document_type,invoice_no,party_name,posting_date,due_date,currency,party_account_key,document_status,net_total,taxable_sales,vat_amount,creditable_input_vat,grand_total,outstanding_amount,created_by_admin_key,updated_by_admin_key) VALUES(?,?,?,?,?,?,?,?,'PHP',?,'SUBMITTED',?,?,?,?,?,?,?,?)";$d->Execute($header,[$keys['sales'],$c['company_key'],$c['company_key_hash'],'SALES','SI-'.$s,'Customer','2026-05-01','2026-05-31',$keys['cash'],'1000','1000','120','0','1120','1120',$a['admin_key'],$a['admin_key']]);$d->Execute($header,[$keys['purchase'],$c['company_key'],$c['company_key_hash'],'PURCHASE','PI-'.$s,'Supplier','2026-05-02','2026-05-31',$keys['cash'],'500','0','60','60','560','560',$a['admin_key'],$a['admin_key']]);$d->Execute("INSERT INTO project_company_finance_invoice_tax(invoice_tax_key,invoice_key,invoice_line_key,company_key,company_key_hash,tax_code,tax_name,tax_kind,bir_classification,rate,taxable_base,vat_amount,creditable_input_vat,non_creditable_input_vat,creditable_vat_withheld,tax_snapshot_json) VALUES(?,?,?,?,?,'INPUT_SERVICE_VAT12','Input VAT','VAT','INPUT_SERVICE',12,500,60,60,0,0,'{}')",[bx_uuid(),$keys['purchase'],bx_uuid(),$c['company_key'],$c['company_key_hash']]);$vat=yovel_admin_bir_2550q_report($c,2026,2);report_assert($vat['sales']['output']==='120.000000'&&$vat['allowable_input_tax']==='60.000000'&&$vat['net_vat_payable']==='60.000000','BIR 2550Q report failed.');}finally{$h=$c['company_key_hash'];$d->Execute('DELETE FROM project_company_finance_invoice_tax WHERE company_key_hash=? AND invoice_key IN (?,?)',[$h,$keys['sales'],$keys['purchase']]);$d->Execute('DELETE FROM project_company_finance_invoice WHERE company_key_hash=? AND invoice_key IN (?,?)',[$h,$keys['sales'],$keys['purchase']]);$d->Execute('DELETE FROM project_company_general_ledger_entry WHERE company_key_hash=? AND account_key IN (?,?,?,?)',[$h,$keys['cash'],$keys['equity'],$keys['income'],$keys['expense']]);$d->Execute('DELETE FROM project_company_general_ledger_transaction WHERE company_key_hash=? AND voucher_no IN (?,?)',[$h,'FUND-'.$s,'OPS-'.$s]);$d->Execute('DELETE FROM project_company_accounting_account WHERE company_key_hash=? AND account_key IN (?,?,?,?)',[$h,$keys['cash'],$keys['equity'],$keys['income'],$keys['expense']]);}echo "Accounting/Finance report checks passed.\n";
